#!/usr/bin/env node
// Builds the self-contained scripts the hosts ship from mermaid-actions.js (the one source of truth).
//   node build-hosts.mjs          write the generated files
//   node build-hosts.mjs --check  fail if a generated file is stale (for CI)
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = dirname(fileURLToPath(import.meta.url));
const read = p => readFileSync(join(root, p), 'utf8');

const lib = read('mermaid-actions.js');
const m = /^export \{([^}]*)\};\s*$/m.exec(lib);
if (!m || (lib.match(/^export\s/gm) ?? []).length !== 1) throw new Error('mermaid-actions.js must end with a single `export { … };`');
const names = m[1].split(',').map(s => s.trim()).filter(Boolean);
const iife = `(() => {\n${lib.slice(0, m.index)}return { ${names.join(', ')} };\n})()`;

const wrap = file =>
  `// GENERATED by build-hosts.mjs from mermaid-actions.js and ${file}. Edit those, not this file.\n` +
  `const MermaidActions = ${iife};\n${read(file)}`;

const outputs = {
  'obsidian/main.js': wrap("obsidian/main.src.js"),
  'vscode/extension.js': wrap('vscode/extension.src.js'),
  'vscode/media/preview.js': `(() => {\n${wrap('vscode/media/preview.src.js')}\n})();\n`,
};

let stale = 0;
for (const [path, text] of Object.entries(outputs)) {
  if (process.argv.includes('--check')) {
    let have = ''; try { have = read(path); } catch {}
    if (have !== text) { console.error(`stale: ${path}`); stale++; }
  } else writeFileSync(join(root, path), text);
}
if (stale) process.exit(1);
